# Studyo 0.5.55 yamasi: resim olarak konmus gazete kupuru metinden cikar (resmi olan sayfada resme bitisik kucuk puntolu dar
# sutun; ustu ve alti resim/kupur olan baslik, tarih, muhabir adi - yalniz sayfada kucuk yazi varsa). Govde paragrafi, dipnot ve
# resimler arasindaki bolum basligi kalir. 0.5.54 uzerine. Kod klasorunde: python3 studyo_0555_yama.py; ardindan kitaplar yeniden islenmeli.
# Tekrar calistirilabilir: dosya zaten yeniyse ATLANDI; ne eski ne yeniyse hicbir seye dokunmadan HATA.
import base64, hashlib, os, sys, zlib
D = [
    ('kutuphane/kaynak.py', '7a8908017300424abdbd0c07bf9f8784', 'd1f30473d2a8a2b638c6f7958e15fe71',
     ''),
    ('kutuphane/main.py', 'd91f7f652cf67b03724d4c8fe5380818', 'b205e30829f3f574b28169b354555230',
     ''),
    ('tests/test_0555.py', None, 'b68f29c1811aa4c9e3d90b861293604a',
     ''),
]
md5 = lambda p: hashlib.md5(open(p, 'rb').read()).hexdigest() if os.path.exists(p) else None
for yol, eski, yeni, _ in D:
    m = md5(yol)
    if m not in (eski, yeni):
        print('HATA:', yol, 'beklenmeyen icerik (md5', m, ') - hicbir dosya degistirilmedi'); sys.exit(1)
for yol, eski, yeni, veri in D:
    if md5(yol) == yeni:
        print('ATLANDI (zaten yeni):', yol); continue
    icerik = zlib.decompress(base64.b64decode(veri))
    assert hashlib.md5(icerik).hexdigest() == yeni
    os.makedirs(os.path.dirname(yol) or '.', exist_ok=True)
    open(yol, 'wb').write(icerik)
    print('YAZILDI:', yol, yeni)
print('TAMAM')
